union absoluteValue
{
    double d;
    uint64_t u;
};

static inline double negateDouble(double value)
{
    union absoluteValue abs;
    abs.d = value;
    abs.u = (abs.u | 1UL << 63); // Set the sign bit to ensure a negative value
    return abs.d;
}

