double scoreIoc(LETTER *text, size_t length)
{
    int counts[26] = {0};
    int N = 0;

    // Count each letter
    for (size_t i = 0; i < length; i++)
    {
        LETTER c = text[i];
        if (c < 26)
        {
            counts[c]++;
            N++;
        }
    }

    // Calculate numerator: sum of n_i * (n_i - 1)
    long numerator = 0;

    for (int i = 0; i < 26; i++)
    {
        numerator += counts[i] * (counts[i] - 1);
    }

    // N * (N - 1)
    long denominator = N * (N - 1);

    double raw = (double)numerator / denominator;

    return negateDouble(raw - expectedIOC);
}

double scoreUnigrams(LETTER *text, size_t length)
{
    double score = 0.0;

    for (size_t i = 0; i < length; i++)
    {
        LETTER c = text[i];
        if (c < 26)
        {
            score += unigrams[c];
        }
    }

    return score / length;
}

double scoreBigrams(LETTER *text, size_t length)
{
    double score = 0.0;

    for (size_t i = 0; i < length - 1; i++)
    {
        LETTER c1 = text[i];
        LETTER c2 = text[i + 1];
        if (c1 < 26 && c2 < 26)
        {
            score += bigrams[(c1 * 26) + c2];
        }
    }

    return score / (length - 1);
}

double scoreTrigrams(LETTER *text, size_t length)
{
    double score = 0.0;

    for (size_t i = 0; i < length - 2; i++)
    {
        LETTER c1 = text[i];
        LETTER c2 = text[i + 1];
        LETTER c3 = text[i + 2];
        if (c1 < 26 && c2 < 26 && c3 < 26)
        {
            score += trigrams[(c1 * 26 * 26) + (c2 * 26) + c3];
        }
    }

    return score / (length - 2);
}
